import sys

class Solution:
    def boxValue(self, s: str) -> int:
        sys.setrecursionlimit(10000)
        MOD = 10**9 + 7
        def value(lo, hi):
            total, depth, start = 0, 0, lo
            for i in range(lo, hi):
                depth += 1 if s[i] == "(" else -1
                if depth == 0:
                    inner = 1 if i == start + 1 else 2 * value(start + 1, i)
                    total = (total + inner) % MOD
                    start = i + 1
            return total
        return value(0, len(s))

