class Solution {
    private static final long MOD = 1_000_000_007L;
    private String s;

    public int boxValue(String s) {
        this.s = s;
        return (int) value(0, s.length());
    }

    private long value(int lo, int hi) {
        long total = 0;
        int depth = 0, start = lo;
        for (int i = lo; i < hi; i++) {
            depth += s.charAt(i) == '(' ? 1 : -1;
            if (depth == 0) {
                long inner = (i == start + 1) ? 1 : 2 * value(start + 1, i) % MOD;
                total = (total + inner) % MOD;
                start = i + 1;
            }
        }
        return total;
    }
}

