class Solution {
    public int boxValue(String s) {
        final long MOD = 1_000_000_007L;
        long[] stack = new long[s.length() + 1];
        int top = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') stack[++top] = 0;
            else {
                long t = stack[top--];
                stack[top] = (stack[top] + (s.charAt(i - 1) == '(' ? 1 : 2 * t)) % MOD;
            }
        }
        return (int) stack[0];
    }
}

