int boxValue(char* s) {
    const long long MOD = 1000000007LL;
    int n = strlen(s), top = 0;
    long long* stack = calloc(n + 1, sizeof(long long));
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') stack[++top] = 0;
        else {
            long long t = stack[top--];
            stack[top] = (stack[top] + (s[i - 1] == '(' ? 1 : 2 * t)) % MOD;
        }
    }
    int answer = (int) stack[0];
    free(stack);
    return answer;
