        int n = s.length();
        long[] pow2 = new long[n / 2 + 1];
        pow2[0] = 1;
        for (int d = 1; d < pow2.length; d++) pow2[d] = pow2[d - 1] * 2 % MOD;
        long total = 0;
        int depth = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == '(') depth++;
            else {
                depth--;
                if (s.charAt(i - 1) == '(') total = (total + pow2[depth]) % MOD;
            }
        }
        return (int) total;
    }
}

