    int n = strlen(s);
    long long* pow2 = malloc((n / 2 + 1) * sizeof(long long));
    pow2[0] = 1;
    for (int d = 1; d <= n / 2; d++) pow2[d] = pow2[d - 1] * 2 % MOD;
